let sliceQueue=[],sliceQueueIndex=0,queueActive=false;
const queuePlayer=document.createElement('section');queuePlayer.className='queue-player';queuePlayer.hidden=true;queuePlayer.setAttribute('aria-label','Slice exploration queue');queuePlayer.innerHTML='<div class="queue-player-top"><strong id="queue-progress-label" role="status"></strong><button id="exit-slice-queue">Exit queue</button></div><progress id="queue-progress" aria-label="Queue progress"></progress><div class="queue-player-controls"><p id="queue-next-title"></p><button id="queue-prev">← Previous</button><button id="queue-next" class="dark">Next →</button></div>';document.querySelector('#dialog-stage').before(queuePlayer);
function refreshSliceQueue(){queuePlayer.hidden=!queueActive;document.querySelector('#next-work').hidden=queueActive;if(!queueActive)return;const total=sliceQueue.length,last=sliceQueueIndex===total-1;document.querySelector('#queue-progress-label').textContent='SLICE QUEUE · '+(sliceQueueIndex+1)+' / '+total;const progress=document.querySelector('#queue-progress');progress.max=total;progress.value=sliceQueueIndex+1;document.querySelector('#queue-next-title').textContent=last?'That was the last experience. Where will your curiosity take you next?':'Up next: '+works.find(w=>w.id===sliceQueue[sliceQueueIndex+1]).title;document.querySelector('#queue-prev').disabled=sliceQueueIndex===0;document.querySelector('#queue-next').textContent=last?'Finish exploring ✓':'Next →'}
const queueOpenBefore=openWork;openWork=function(id,remix=false){if(queueActive&&(remix||id!==sliceQueue[sliceQueueIndex]))queueActive=false;queueOpenBefore(id,remix);refreshSliceQueue()};
document.querySelector('#start-slice-queue').onclick=()=>{sliceQueue=['orbit',...works.filter(w=>w.id!=='orbit'&&!w.local).map(w=>w.id)];sliceQueueIndex=0;queueActive=true;openWork(sliceQueue[0])};document.querySelector('#queue-prev').onclick=()=>{if(sliceQueueIndex>0){sliceQueueIndex--;openWork(sliceQueue[sliceQueueIndex])}};document.querySelector('#queue-next').onclick=()=>{if(sliceQueueIndex<sliceQueue.length-1){sliceQueueIndex++;openWork(sliceQueue[sliceQueueIndex])}else{queueActive=false;refreshSliceQueue();dialog.close();toast('Queue complete. Keep exploring new ideas.')}};document.querySelector('#exit-slice-queue').onclick=()=>{queueActive=false;refreshSliceQueue()};dialog.addEventListener('close',()=>{queueActive=false;refreshSliceQueue()});
